// A variable whose value is known only at runtime
int get_runtime_size();
int runtime_sz = get_runtime_size();

// A const variable initialized with a runtime value
const auto const_size = runtime_sz; // OK

// An array cannot be sized with a runtime const
// int arr1[const_size]; // Error!

// constexpr guarantees a compile-time value
constexpr int compile_time_sz = 10; // OK, 10 is a literal

// Error: initializer for a constexpr variable must be a constant expression
// constexpr int bad_sz = runtime_sz; // Error!

// OK: constexpr can be used where compile-time constants are required
int arr2[compile_time_sz];
std::array<int, compile_time_sz> data;
